package com.jansetu.integration.storage;

import java.io.InputStream;

/**
 * Private object storage for document bytes (ADR-003). Keys are opaque random identifiers generated by the
 * document module; user-supplied file names are never used as storage keys.
 */
public interface DocumentStoragePort {

    void put(String key, byte[] content);

    InputStream get(String key);

    void delete(String key);
}
